#!/usr/bin/env node
// OWNER: t2a (wave 1).
//
// `npm run api:check` — the typed client committed in src/api is exactly what
// `npm run api:gen` produces from the committed openapi/openapi.json.
//
// It regenerates with the SAME config (openapi-ts.config.ts, loaded by hey-api
// itself) into a temporary directory and compares file by file:
//   - every regenerated file must exist in src/api with identical bytes;
//   - every file in src/api that carries the generator header must still be
//     generated (a stale file left behind by output.clean: false fails here);
//   - files without the header are hand-written (ext.ts, transport.ts, …) and are
//     skipped — but none may be named *.gen.ts or live under client/ or core/,
//     because ESLint ignores those paths and a hand-written file there would
//     escape the linter.
// On a mismatch it prints a unified diff and exits 1; if generation itself fails
// it exits 2. Offline: the input is the committed file, never a live URL.
import { spawnSync } from "node:child_process";
import { copyFileSync, existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";

const HEADER = "// This file is auto-generated by @hey-api/openapi-ts";
const web = join(dirname(fileURLToPath(import.meta.url)), "..");
const committedDir = join(web, "src", "api");

function walk(dir, base = dir) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true })
    .flatMap((entry) => {
      const full = join(dir, entry.name);
      return entry.isDirectory() ? walk(full, base) : [relative(base, full).split(sep).join("/")];
    })
    .sort();
}

const isGeneratedFile = (full) => readFileSync(full, "utf8").startsWith(HEADER);

function firstDifference(a, b) {
  const la = a.split("\n");
  const lb = b.split("\n");
  for (let i = 0; i < Math.max(la.length, lb.length); i++) {
    if (la[i] !== lb[i]) return `line ${i + 1}\n      committed:   ${JSON.stringify(la[i] ?? "<end of file>")}\n      regenerated: ${JSON.stringify(lb[i] ?? "<end of file>")}`;
  }
  return "identical text, different bytes";
}

process.chdir(web); // openapi-ts.config.ts resolves its paths from web/
const tmp = mkdtempSync(join(tmpdir(), "witness-api-check-"));
const regeneratedDir = join(tmp, "regenerated");
let exitCode = 0;

try {
  try {
    const { createClient } = await import("@hey-api/openapi-ts");
    // Merged over openapi-ts.config.ts: only the destination (and the noise) change.
    await createClient({ output: { path: regeneratedDir }, logs: { level: "silent", file: false } });
  } catch (error) {
    console.error(`api:check: generation failed — ${error?.stack ?? error}`);
    exitCode = 2;
    throw error;
  }

  const regenerated = walk(regeneratedDir);
  if (regenerated.length === 0) {
    console.error("api:check: the generator produced no files — check openapi-ts.config.ts");
    exitCode = 2;
    throw new Error("empty output");
  }
  const committed = walk(committedDir);
  const regeneratedSet = new Set(regenerated);
  const problems = [];
  const handWritten = [];
  const differing = [];

  for (const file of regenerated) {
    const mine = join(committedDir, file);
    if (!existsSync(mine)) {
      problems.push(`missing      src/api/${file} (run npm run api:gen and commit it)`);
      continue;
    }
    const a = readFileSync(mine);
    const b = readFileSync(join(regeneratedDir, file));
    if (!a.equals(b)) {
      differing.push(file);
      problems.push(`differs      src/api/${file} — ${firstDifference(a.toString("utf8"), b.toString("utf8"))}`);
    }
  }
  for (const file of committed) {
    if (regeneratedSet.has(file)) continue;
    const full = join(committedDir, file);
    if (isGeneratedFile(full)) {
      problems.push(`stale        src/api/${file} carries the generator header but is no longer generated (delete it)`);
    } else if (/\.gen\.[cm]?[jt]sx?$/.test(file) || /^(client|core)\//.test(file)) {
      problems.push(`misplaced    src/api/${file} is hand-written in a path ESLint ignores (*.gen.ts, client/, core/)`);
    } else {
      handWritten.push(file);
    }
  }

  if (problems.length) {
    exitCode = 1;
    console.error(`api:check: src/api does not match a fresh \`npm run api:gen\` (${problems.length} problem${problems.length === 1 ? "" : "s"}):`);
    for (const p of problems) console.error(`  ${p}`);
    if (differing.length) {
      // Two sibling trees holding only the differing files, so the diff paths read cleanly.
      for (const [label, from] of [
        ["committed", committedDir],
        ["regenerated", regeneratedDir],
      ]) {
        for (const file of differing) {
          const to = join(tmp, "diff", label, "src", "api", file);
          mkdirSync(dirname(to), { recursive: true });
          copyFileSync(join(from, file), to);
        }
      }
      const git = spawnSync("git", ["diff", "--no-index", "--no-color", "--", "committed", "regenerated"], { cwd: join(tmp, "diff"), encoding: "utf8" });
      if (git.error) console.error("  (git is unavailable; the first differing line of each file is listed above)");
      else process.stderr.write(git.stdout.split("\n").slice(0, 400).join("\n") + "\n");
    }
  } else {
    console.log(`api:check: src/api matches the generator — ${regenerated.length} generated files identical; hand-written: ${handWritten.join(", ") || "none"}`);
  }
} catch (error) {
  if (exitCode === 0) {
    console.error(`api:check: ${error?.stack ?? error}`);
    exitCode = 2;
  }
} finally {
  rmSync(tmp, { recursive: true, force: true });
}
process.exit(exitCode);
